<script setup lang="ts">
import { ref, onUnmounted } from 'vue'
import SnapshotPreview from './SnapshotPreview.vue'
import type {PartAsset} from '../parts/schema'
defineEmits<{close:[]}>()
const project=ref(localStorage.getItem('gs-godot-project')??''),assets=ref<any[]>([]),error=ref(''),busy=ref(false),status=ref(''),newId=ref(''),image=ref(''),normal=ref('')
const bound=ref(false),activeJob=ref('')
const preview=ref<{part:PartAsset;geometryHash:string;snapshotHash:string}>()
let closed=false
onUnmounted(()=>{closed=true})
async function call(name:string,args:Record<string,unknown>={}){const r=await fetch('/api/godot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,arguments:args})});const data=await r.json();if(!r.ok)throw Error(data.error??'Godot service unavailable');return data}
async function run(action:()=>Promise<void>){busy.value=true;error.value='';try{await action()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function refresh(){assets.value=(await call('gs_list_assets')).assets}
async function refreshJobs(){for(const a of assets.value){if(a.generationJob&&!a.model)await call('gs_generation_status',{id:a.id})}await refresh();status.value='状态已刷新'}
async function bind(){bound.value=false;assets.value=[];const connection=await call('gs_bind_project',{project:project.value});project.value=connection.project;bound.value=true;localStorage.setItem('gs-godot-project',project.value);await refresh();status.value='已连接 Godot 项目'}
async function register(){await call('gs_register_asset',{id:newId.value,image:image.value,normal:normal.value});await refresh()}
async function generate(id:string){const result=await call('gs_generate_model',{id});status.value='正在生成：'+id;let job=result;while(!closed&&!['succeeded','failed','cancelled'].includes(job.status)){await new Promise(r=>setTimeout(r,2000));job=await call('gs_generation_status',{id});status.value=id+' · '+job.phase}if(job.status==='failed')throw Error(job.error?.message??'生成失败');await refresh()}
async function prepare(id:string){await call('gs_prepare_asset',{id});await refresh();preview.value=await call('gs_preview_asset',{id});status.value='GS 模型快照已准备；导出不会重新配准'}
async function showPreview(id:string){preview.value=await call('gs_preview_asset',{id})}
async function exportAsset(id:string){const result=await call('gs_export_asset',{id});activeJob.value=result.id;let job=result;status.value='正在导出已保存的 GS 快照：'+id;while(!closed&&job.status==='running'){await new Promise(r=>setTimeout(r,1000));job=await call('gs_job_status',{jobId:result.id})}activeJob.value='';if(closed)return;if(job.status==='cancelled'){status.value='导出已取消';return}if(job.status==='failed')throw Error(job.log);status.value='导出完成：'+id+'，可在 Godot 中实例化';await refresh()}
</script>
<template><Teleport to="body"><div class="backdrop"><section role="dialog" aria-modal="true" aria-label="Godot 资产导出"><header><strong>Godot 资产导出</strong><button @click="$emit('close')">关闭</button></header><p>绑定包含 project.godot 的本地目录。生成资源写入 assets/gstudio，通用运行时写入 addons/gstudio_2d。</p><label>项目根目录<input v-model="project" @input="bound=false;assets=[]" placeholder="C:/projects/my-game"/></label><button :disabled="busy" @click="run(bind)">连接项目</button><button :disabled="busy||!bound" @click="run(async()=>{await call('gs_install_runtime');status='运行时已安装'})">安装 / 更新运行时</button><button :disabled="busy||!bound" @click="run(refreshJobs)">刷新模型状态</button><hr/><div class="register"><input v-model="newId" placeholder="资产 ID（英文）"/><input v-model="image" placeholder="项目内图片路径"/><input v-model="normal" placeholder="项目内法线图路径"/><button :disabled="busy||!bound" @click="run(register)">登记资产</button></div><article v-for="a in assets" :key="a.id"><span>{{a.id}}</span><span>{{a.model?'模型就绪':'尚无模型'}}</span><button :disabled="busy" @click="run(()=>generate(a.id))">生成模型</button><button :disabled="busy||!a.model" @click="run(()=>prepare(a.id))">准备 GS 模型</button><button :disabled="busy||!a.snapshot" @click="run(()=>showPreview(a.id))">预览快照</button><button :disabled="busy||!a.snapshot" @click="run(()=>exportAsset(a.id))">导出场景</button></article><SnapshotPreview v-if="preview" :key="preview.snapshotHash" :part="preview.part" :expected-hash="preview.geometryHash"/><p role="status">{{status}}</p><button v-if="busy&&activeJob" @click="call('gs_cancel_export',{jobId:activeJob}).catch(e=>error=String(e))">取消导出</button><pre v-if="error" role="alert">{{error}}</pre></section></div></Teleport></template>
<style scoped>.backdrop{position:fixed;inset:0;background:#0009;z-index:3000;display:grid;place-items:center}section{background:#252525;color:#ddd;padding:20px;width:min(760px,90vw);max-height:85vh;overflow:auto;border:1px solid #555;border-radius:8px;font:13px system-ui}header,article{display:flex;align-items:center;gap:12px;justify-content:space-between}article{padding:12px 0;border-bottom:1px solid #444}button,input{font:inherit;background:#333;color:#ddd;border:1px solid #555;border-radius:4px;padding:7px;margin:4px}label{display:flex;align-items:center}label input{flex:1}.register{display:flex;flex-wrap:wrap}pre{white-space:pre-wrap;color:#f99}button:disabled{opacity:.4}</style>
